230	func TestCertificateNumberIdempotencyAndConflict(t *testing.T) {
231		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
232		l := newTestLedger(t, clock)
233		mustRegister(t, l, "M-1", "万用表", 0.5)
