611		first := certArgs(target, "C-1", "2026-09-01", "-f备用.json", "--json")
612		if r := runArgs(t, first...); r.code != 0 {
613			t.Fatal(r.stderr)
614		}
615		r := runArgs(t, first...)
616		if r.code != 0 || !strings.Contains(r.stdout, "未增加历史") {
617			t.Fatalf("同号同内容应幂等返回原证书，code=%d stdout=%q", r.code, r.stdout)
618		}
619		conflict := certArgs(target, "C-1", "2026-09-01", "-f备用.json", "别的摘要")
620		if r := runArgs(t, conflict...); r.code != 1 {
621			t.Fatalf("同号内容不同应冲突退出 1，得到 %d", r.code)
