164	func mustReviewJSON(t *testing.T, path, id string) cliReview {
165		t.Helper()
166		r := runArgs(t, "review", "--id", id, "-f", path, "--json")
167		if r.code != 0 {
168			t.Fatalf("review %s 失败 code=%d stderr=%s", id, r.code, r.stderr)
169		}
170		var v cliReview
171		if err := json.Unmarshal([]byte(r.stdout), &v); err != nil {
172			t.Fatalf("review JSON 解析失败: %v\n%s", err, r.stdout)
173		}
174		return v
175	}
